59	  /* ---------- Scroll reveal ---------- */
60	  var revs = $$(".reveal, .mask");
61	  if (reduce || !("IntersectionObserver" in window)) {
62	    revs.forEach(function (el) { el.classList.add("in"); });
63	  } else {
64	    var io = new IntersectionObserver(function (entries) {
65	      entries.forEach(function (en) {
66	        if (en.isIntersecting) { en.target.classList.add("in"); io.unobserve(en.target); }
67	      });
