72	  /* ---------- Header solidify + scroll progress + floating CTA ---------- */
73	  var header = $("#header"), progress = $("#progress"), floating = $("#floating"), hero = $("#hero");
74	  function onScroll() {
75	    var st = window.pageYOffset || document.documentElement.scrollTop;
76	    if (header) header.classList.toggle("solid", st > 60);
77	    if (progress) {
78	      var h = document.documentElement.scrollHeight - window.innerHeight;
