129	  /* ---------- Contact form: graceful mailto fallback ---------- */
130	  var form = $("#inquiryForm");
131	  if (form) {
132	    var KAYLEE_EMAIL = "kbamvideo@gmail.com";
133	    var note = $(".form__note", form);
134	
135	    var confirm = function (name) {
136	      if (!note) return;
137	      note.innerHTML =
138	        "Your email app should be opening now with your message ready to send. " +
139	        "If nothing opened, email me directly at " +
140	        "<a href=\"mailto:" + KAYLEE_EMAIL + "\" data-cursor>" + KAYLEE_EMAIL + "</a> " +
141	        "<button type=\"button\" class=\"form__copy\" data-cursor>Copy email</button>";
142	      note.classList.add("form__note--sent");
143	      var copyBtn = $(".form__copy", note);
144	      if (copyBtn) copyBtn.addEventListener("click", function () {
145	        var done = function () { copyBtn.textContent = "Copied ✓"; };
146	        if (navigator.clipboard && navigator.clipboard.writeText) {
147	          navigator.clipboard.writeText(KAYLEE_EMAIL).then(done, done);
148	        } else {
149	          var t = document.createElement("textarea");
150	          t.value = KAYLEE_EMAIL; document.body.appendChild(t); t.select();
151	          try { document.execCommand("copy"); } catch (err) {}
152	          document.body.removeChild(t); done();
153	        }
154	      });
155	    };
156	
157	    form.addEventListener("submit", function (e) {
158	      var action = form.getAttribute("action") || "";
159	      var configured = action.indexOf("formspree.io/f/") > -1 && action.indexOf("your-form-id") === -1;
160	      if (configured) return; // real endpoint set — let it POST
161	      e.preventDefault();
162	      var get = function (n) { var el = form.elements[n]; return el ? el.value.trim() : ""; };
163	      var name = get("name"), email = get("email");
164	      if (!name || !email) {
165	        var first = !name ? form.elements["name"] : form.elements["email"];
166	        if (first) first.focus();
167	        return;
168	      }
169	      var body =
170	        "Name: " + name + "\n" +
171	        "Partner: " + get("partner") + "\n" +
172	        "Wedding date: " + get("date") + "\n" +
173	        "Venue / location: " + get("venue") + "\n" +
174	        "Email: " + email + "\n\n" +
175	        get("message");
176	      var href = "mailto:" + KAYLEE_EMAIL + "?subject=" +
177	        encodeURIComponent("Wedding film inquiry — " + name) +
178	        "&body=" + encodeURIComponent(body);
179	      window.location.href = href;
180	      confirm(name);
181	    });
182	  }
