184	  /* ---------- Custom cursor ---------- */
185	  if (fine && !reduce) {
186	    var cursor = $("#cursor");
187	    if (cursor) {
188	      document.body.classList.add("cursor-on");
189	      var cx = window.innerWidth / 2, cy = window.innerHeight / 2, tx = cx, ty = cy;
190	      window.addEventListener("mousemove", function (e) { tx = e.clientX; ty = e.clientY; }, { passive: true });
191	      (function loop() {
192	        cx += (tx - cx) * 0.2; cy += (ty - cy) * 0.2;
193	        cursor.style.transform = "translate(" + cx + "px," + cy + "px)";
194	        requestAnimationFrame(loop);
195	      })();
196	      document.addEventListener("mouseover", function (e) {
197	        var film = e.target.closest("[data-cursor-film]");
198	        var link = e.target.closest("a,button,[data-cursor],input,textarea");
199	        cursor.classList.toggle("is-film", !!film);
