201	      });
202	      document.addEventListener("mouseout", function (e) {
203	        if (!e.relatedTarget) { cursor.classList.remove("is-film", "is-hover"); }
204	      });
205	      window.addEventListener("mouseleave", function () { cursor.style.opacity = "0"; });
206	      window.addEventListener("mouseenter", function () { cursor.style.opacity = "1"; });
207	    }
208	  }
209	})();
