1	import { readFileSync } from 'node:fs';
2	import { scryptSync, createDecipheriv } from 'node:crypto';
3	import { PrismaClient } from '@prisma/client';
4	
5	// load AUTH_SECRET from .env
6	const env = readFileSync('/opt/nxeon/.env','utf8');
7	for (const line of env.split('\n')) {
8	  const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)$/);
9	  if (m) { let v = m[2].trim().replace(/^["']|["']$/g,''); if(!process.env[m[1]]) process.env[m[1]] = v; }
10	}
11	function deriveKey(){ const s=process.env.AUTH_SECRET; if(!s) throw new Error('no AUTH_SECRET'); return scryptSync(s,'nxeon-byok',32); }
12	function decryptSecret(enc){ if(!enc) return null; try{ const [i,t,d]=enc.split(':'); const de=createDecipheriv('aes-256-gcm',deriveKey(),Buffer.from(i,'base64')); de.setAuthTag(Buffer.from(t,'base64')); return Buffer.concat([de.update(Buffer.from(d,'base64')),de.final()]).toString('utf8'); }catch(e){return null;} }
13	
14	const p = new PrismaClient();
15	const s = await p.server.findUnique({ where:{ id:'cmsecmdps0001hlp27ai6mr7c' }, select:{ id:true,name:true,ipAddress:true,hostname:true,rootPasswordEnc:true } });
16	if(!s){ console.log('SERVER_NOT_FOUND'); process.exit(1); }
17	const pw = decryptSecret(s.rootPasswordEnc);
18	console.log(JSON.stringify({ id:s.id, name:s.name, ip:s.ipAddress, hostname:s.hostname, pwOk: !!pw, pwLen: pw?pw.length:0 }));
