/* ---------- Testimonials slider (only activates with 2+ real reviews) ---------- */
var qTrack = $("#quotesTrack"), qNav = $("#quotesNav");
if (qTrack && qNav) {
  var items = $$(".quote__item", qTrack), dotsWrap = $("#quotesDots");
  if (items.length > 1 && dotsWrap) {
    var qIdx = 0, qTimer = null;
    var goto = function (n) {
      qIdx = (n + items.length) % items.length;
      qTrack.style.transform = "translateX(" + (-qIdx * 100) + "%)";
      $$(".quotes__dot", dotsWrap).forEach(function (d, i) {
        d.classList.toggle("is-active", i === qIdx);
        d.setAttribute("aria-selected", i === qIdx ? "true" : "false");
      });
    };
    var restart = function () {
      if (reduce) return;
      window.clearInterval(qTimer);
      qTimer = window.setInterval(function () { goto(qIdx + 1); }, 7000);
    };
    items.forEach(function (_, i) {
      var d = document.createElement("button");
      d.className = "quotes__dot" + (i === 0 ? " is-active" : "");
      d.type = "button"; d.setAttribute("role", "tab");
      d.setAttribute("aria-label", "Review " + (i + 1));
      d.addEventListener("click", function () { goto(i); restart(); });
      dotsWrap.appendChild(d);
    });
    $$(".quotes__arrow", qNav).forEach(function (b) {
      b.addEventListener("click", function () {
        goto(qIdx + parseInt(b.getAttribute("data-dir"), 10)); restart();
      });
    });
    qNav.hidden = false;
    goto(0); restart();
  }
}

